package mrpapermoon.whisper.mesh.dbimport androidx.room.Databaseimport androidx.room.RoomDatabaseimport androidx.room.TypeConvertersimport mrpapermoon.whisper.mesh.transformation.RoomTypeConverters@Database(	entities = [		NetworkMessageEntity::class,		WhispererEntity::class,	],	version = 1,	exportSchema = false)@TypeConverters(RoomTypeConverters::class)abstract class RumorDatabase : RoomDatabase() {	abstract fun networkMessageDao(): NetworkMessageDao	abstract fun whispererDao(): WhispererDao}